const queries = {"PudoLocationSearch":"query PudoLocationSearch($isUserTriggeredFallback: Boolean, $latitude: Float!, $longitude: Float!, $query: String!, $type: EnumRVWebCommonPickupOrDropoff!) {\n  pudoLocationSearch(\n    isUserTriggeredFallback: $isUserTriggeredFallback\n    latitude: $latitude\n    longitude: $longitude\n    query: $query\n    type: $type\n  ) {\n    ...PudoLocationSearchFragment\n    __typename\n  }\n}\n\nfragment PudoLocationSearchFragment on RVWebCommonPudoLocation {\n  savedPlacesMeta {\n    label\n    tag\n    __typename\n  }\n  ...PudoFragmentBase\n  __typename\n}\n\nfragment PudoFragmentBase on RVWebCommonPudoLocation {\n  addressLine1\n  addressLine2\n  categories\n  confidence\n  id\n  source\n  provider\n  tag\n  type\n  __typename\n}\n","Activities":"query Activities($cityID: Int, $endTimeMs: Float, $includePast: Boolean = true, $includeUpcoming: Boolean = true, $limit: Int = 5, $nextPageToken: String, $orderTypes: [RVWebCommonActivityOrderType!] = [RIDES, TRAVEL], $profileType: RVWebCommonActivityProfileType = PERSONAL, $startTimeMs: Float) {\n  activities(cityID: $cityID) {\n    cityID\n    past(\n      endTimeMs: $endTimeMs\n      limit: $limit\n      nextPageToken: $nextPageToken\n      orderTypes: $orderTypes\n      profileType: $profileType\n      startTimeMs: $startTimeMs\n    ) @include(if: $includePast) {\n      activities {\n        ...RVWebCommonActivityFragment\n        __typename\n      }\n      nextPageToken\n      __typename\n    }\n    upcoming @include(if: $includeUpcoming) {\n      activities {\n        ...RVWebCommonActivityFragment\n        __typename\n      }\n      __typename\n    }\n    __typename\n  }\n}\n\nfragment RVWebCommonActivityFragment on RVWebCommonActivity {\n  buttons {\n    isDefault\n    startEnhancerIcon\n    text\n    url\n    __typename\n  }\n  cardURL\n  description\n  imageURL {\n    light\n    dark\n    __typename\n  }\n  subtitle\n  title\n  uuid\n  __typename\n}\n"};
async function gql(operationName,query,variables={},path='/graphql') { const r=await fetch(path,{method:'POST',credentials:'include',cache:'no-store',headers:{'content-type':'application/json','x-csrf-token':'x'},body:JSON.stringify({operationName,query,variables})}); if(!r.ok)throw new Error('Uber read failed: HTTP '+r.status); const j=await r.json(); if(j.errors?.length)throw new Error('Uber query failed; session or request could not be verified'); if(!j.data)throw new Error('Unexpected Uber response'); return j.data; }
async function user(){ const d=await gql('CurrentUserRidersWeb','query CurrentUserRidersWeb { currentUser { uuid firstName lastName rating __typename } }'); if(!d.currentUser||d.currentUser.__typename!=='RVWebCommonUser')throw new Error('Uber session unverified. Sign in to Uber; signed-out response classification is not yet verified.');return d.currentUser; }
const mapActivity=x=>({title:String(x.title??''),subtitle:x.subtitle??null,description:x.description??null,url:x.cardURL??null});
window.ox.install(({action})=>{
action('listSessions',{async invoke(){const u=await user();if(typeof u.uuid!=='string'||!u.uuid)throw new Error('Uber account identity unavailable');const label=[u.firstName,u.lastName].filter(Boolean).join(' ')||'Uber rider';return [{id:u.uuid,label,url:'https://riders.uber.com/trips'}];}});
action('login',{async invoke(){location.assign('https://m.uber.com/go/login-redirect');return null;}});
action('getProfile',{async invoke(){const u=await user();const n=u.rating==null?null:Number(u.rating);return {firstName:u.firstName??null,lastName:u.lastName??null,rating:Number.isFinite(n)?n:null};}});
action('listTrips',{async invoke(args){const d=await gql('Activities',queries.Activities,{includePast:true,includeUpcoming:false,limit:args.limit??5,nextPageToken:args.cursor,orderTypes:['RIDES','TRAVEL'],profileType:'PERSONAL'});const p=d.activities?.past;if(!Array.isArray(p?.activities))throw new Error('Unexpected trip history response');return {items:p.activities.map(mapActivity),nextCursor:p.nextPageToken||null};}});
action('listUpcomingTrips',{async invoke(){const d=await gql('Activities',queries.Activities,{includePast:false,includeUpcoming:true,limit:5,orderTypes:['RIDES','TRAVEL'],profileType:'PERSONAL'});const p=d.activities?.upcoming;if(!Array.isArray(p?.activities))throw new Error('Unexpected upcoming response');return {items:p.activities.map(mapActivity),nextCursor:null};}});
action('searchLocations',{async invoke(args){const d=await gql('PudoLocationSearch',queries.PudoLocationSearch,{query:args.query,latitude:args.latitude,longitude:args.longitude,type:args.type??'DROPOFF'},'/go/graphql');if(!Array.isArray(d.pudoLocationSearch))throw new Error('Unexpected location response');return {items:d.pudoLocationSearch.slice(0,args.limit??5).map(x=>({id:x.id,addressLine1:x.addressLine1??'',addressLine2:x.addressLine2??'',provider:x.provider??null,confidence:x.confidence??null})),nextCursor:null};}});
action('getBookingUrl',{async invoke(){return {url:'https://m.uber.com/go/home'};}});
});
